import { registerAs } from '@nestjs/config';

/**
 * Canonical seller/billing entity configuration for TRADINGO invoices.
 *
 * All values are read from environment variables.
 * Defaults match the founder-approved canonical billing entity:
 *   Niksa Global Ventures Limited
 *   GSTIN: 07AAKCN7471R1ZH
 *   Address: House No. 194, Block-G, Pocket 6, Sector 16, Rohini, New Delhi - 110089
 *   State: Delhi, State Code: 07 (DL)
 *
 * These values appear on every subscription/invoice PDF generated by the platform.
 */
export const sellerConfig = registerAs('seller', () => ({
  /** Legal entity name — appears as the authoritative seller on invoices */
  legalName: process.env.SELLER_LEGAL_NAME || 'Niksa Global Ventures Limited',

  /** GSTIN — 15-character GST identification number */
  gstin: process.env.SELLER_GSTIN || '07AAKCN7471R1ZH',

  /** Full registered address */
  address: process.env.SELLER_REGISTERED_ADDRESS || 'House No. 194, Block-G, Pocket 6, Sector 16, Rohini, New Delhi - 110089',

  /** Seller's registered state name */
  state: process.env.SELLER_STATE || 'Delhi',

  /** Seller's state code (2-digit, e.g. '07' for Delhi) */
  stateCode: process.env.SELLER_STATE_CODE || '07',

  /** Brand/trading name — used in the "A Brand of X" line */
  brandName: process.env.SELLER_BRAND_NAME || 'TRADINGO',

  /** Entity name for invoice signatory line */
  signatoryEntity: process.env.SELLER_SIGNATORY_ENTITY || 'Niksa Global Ventures Limited',

  /** Support email shown in invoice footer */
  email: process.env.SELLER_EMAIL || 'support@tradingo.com',

  /** Website shown in invoice footer */
  website: process.env.SELLER_WEBSITE || 'www.tradingo.com',
}));